shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/bin/bat/app.rs b/src/bin/bat/app.rs
--- a/src/bin/bat/app.rs
+++ b/src/bin/bat/app.rs
@@ -430,5 +430,48 @@ impl App {

         Ok(styled_components)
     }
 }
+
+#[test]
+fn paging_with_plain() {
+    use PagingMode::{Always, Never, QuitIfOneScreen};
+
+    let cases: &[(&[&str], PagingMode)] = &[
+        (&["--paging=never", "--plain"], Never),
+        (&["--paging=never", "-p"], Never),
+        (&["--plain", "--paging=never"], Never),
+        (&["-p", "--paging=never"], Never),
+        (&["--paging=always", "--plain"], Always),
+        (&["--paging=always", "-p"], Always),
+        (&["--plain", "--paging=always"], Always),
+        (&["-p", "--paging=always"], Always),
+        (&["--plain"], QuitIfOneScreen),
+        (&["-pp"], Never),
+        (&["--plain", "--plain"], Never),
+        (&["--paging=always", "-pp"], Never),
+        (&["-pp", "--paging=always"], Always),
+        (&["--paging=auto", "-pp"], Never),
+        (&["-pp", "--paging=auto"], QuitIfOneScreen),
+        (&["-p", "--paging=always", "-p"], Never),
+    ];
+
+    for &(args, expected) in cases {
+        let app = App {
+            matches: clap_app::build_app(true)
+                .get_matches_from(std::iter::once("bat").chain(args.iter().copied())),
+            interactive_output: true,
+        };
+        let config = app.config(&[]).unwrap();
+
+        assert_eq!(config.paging_mode, expected, "args: {args:?}");
+        assert!(config.style_components.plain(), "args: {args:?}");
+    }
+}
diff --git a/tests/integration_tests.rs b/tests/integration_tests.rs
--- a/tests/integration_tests.rs
+++ b/tests/integration_tests.rs
@@ -1021,6 +1021,37 @@ fn enable_pager_if_pp_flag_comes_before_paging() {
         .stdout(predicate::eq("pager-output\n").normalize());
 }

+#[test]
+fn paging_with_plain_keeps_explicit_pager() {
+    for plain in ["--plain", "-p"] {
+        bat()
+            .env("PAGER", "echo pager-output")
+            .arg("--paging=always")
+            .arg(plain)
+            .arg("test.txt")
+            .assert()
+            .success()
+            .stdout(predicate::eq("pager-output\n").normalize());
+    }
+}
+
+#[test]
+fn paging_with_plain_keeps_plain_style() {
+    for plain in ["--plain", "-p", "-pp"] {
+        bat()
+            .arg(plain)
+            .arg("--paging=never")
+            .arg("--decorations=always")
+            .arg("--color=never")
+            .arg("test.txt")
+            .assert()
+            .success()
+            .stdout(predicate::eq("hello world\n").normalize());
+    }
+}
+
 #[test]
 fn pager_failed_to_parse() {
PATCH
RUSTFLAGS=-Awarnings cargo test --package bat --bin bat --test integration_tests paging_with_plain

